package com.henson.jarvis.phone;
import android.content.res.AssetManager;import android.net.Uri;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public final class LocalSite implements AutoCloseable {
 public interface Callback{void complete(Uri uri)throws Exception;}
 private final ServerSocket server;private final AssetManager assets;private final Callback callback;private final ExecutorService pool=Executors.newFixedThreadPool(6);private volatile boolean closed;
 public LocalSite(AssetManager assets,Callback callback)throws Exception{this.assets=assets;this.callback=callback;ServerSocket listener;try{listener=new ServerSocket(1455,8,InetAddress.getByName("127.0.0.1"));}catch(IOException e){listener=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));}server=listener;Thread thread=new Thread(()->{while(!closed)try{Socket socket=server.accept();pool.execute(()->serve(socket));}catch(IOException ignored){}});thread.setDaemon(true);thread.start();}
 public String origin(){return "http://127.0.0.1:"+server.getLocalPort();}
 private void serve(Socket socket){try(Socket connection=socket){connection.setSoTimeout(15000);BufferedReader in=new BufferedReader(new InputStreamReader(connection.getInputStream(),StandardCharsets.US_ASCII));String first=in.readLine();if(first==null||first.length()>20000)return;String[] parts=first.split(" ");if(parts.length!=3||!parts[0].equals("GET"))return;String line,host=null;int total=first.length();while((line=in.readLine())!=null&&!line.isEmpty()){total+=line.length();if(total>40000)return;if(line.toLowerCase(java.util.Locale.ROOT).startsWith("host:"))host=line.substring(5).trim();}if(!("127.0.0.1:"+server.getLocalPort()).equals(host))return;Uri uri=Uri.parse(origin()+parts[1]);String path=uri.getPath();OutputStream out=connection.getOutputStream();if("/auth/callback".equals(path)){try{callback.complete(uri);html(out,"ChatGPT connected","Your ChatGPT plan is connected. Return to JARVIS to start talking.");}catch(Exception e){html(out,"Sign-in did not finish",safeMessage(e));}return;}if(path==null||path.contains("..")||path.contains("\\")||path.indexOf('\0')>=0)return;if(path.equals("/"))path="/index.html";try(InputStream file=assets.open("site"+path)){headers(out,"200 OK",mime(path));byte[] buffer=new byte[32768];int n;while((n=file.read(buffer))!=-1)out.write(buffer,0,n);}catch(IOException e){headers(out,"404 Not Found","text/plain");out.write("Not found".getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}
 private static String safeMessage(Exception e){String m=e.getMessage();return m==null?"Return to JARVIS and try again.":m.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
 private static void headers(OutputStream out,String code,String type)throws IOException{out.write(("HTTP/1.1 "+code+"\r\nContent-Type: "+type+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\nContent-Security-Policy: default-src 'self'; script-src 'self' 'wasm-unsafe-eval'; worker-src 'self' blob:; style-src 'self'; connect-src 'self'; media-src 'self' blob:; img-src 'self' data:; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));}
 private static String mime(String path){return path.endsWith(".js")||path.endsWith(".mjs")?"application/javascript":path.endsWith(".wasm")?"application/wasm":path.endsWith(".css")?"text/css":path.endsWith(".json")||path.endsWith(".webmanifest")?"application/json":path.endsWith(".html")?"text/html; charset=utf-8":path.endsWith(".svg")?"image/svg+xml":"application/octet-stream";}
 private static void html(OutputStream out,String title,String message)throws IOException{headers(out,"200 OK","text/html; charset=utf-8");out.write(("<!doctype html><html lang=en><meta name=viewport content='width=device-width,initial-scale=1'><link rel=stylesheet href=/style.css><title>JARVIS sign-in</title><main><h2>"+title+"</h2><p>"+message+"</p><p><a href='hensonjarvis://return'>Return to JARVIS</a></p></main></html>").getBytes(StandardCharsets.UTF_8));}
 public void close(){closed=true;try{server.close();}catch(IOException ignored){}pool.shutdownNow();}
}
